   try(var capture=new CaptureLog(dir.resolve("capture"));var hub=new GameHub(cfg,store,accounts);var f=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME)){var clock=(ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();check(clock.awaitTermination(2,TimeUnit.SECONDS),"unrelated fixture clock stopped");var fixtures=List.of(f,p,m,o);for(int i=0;i<4;i++){var pc=fixtures.get(i).session;NativeDirectoryRegression.init(fixtures.get(i),"DebitFrame"+i,0,cfg.classicServerNames().get(0));var c=((List<CharacterSummary>)get(pc,"characters")).get(0);set(pc,"characters",List.of(copy(c,Map.of("objectId",0x3c000001L+i,"level",99,"type",0))));set(pc,"sourceEquipmentMagicStats",SourceEquipmentMagicStats.none());set(pc,"sourcePhysicalGrowthStats",SourcePhysicalGrowthStats.classic381());}FlowRegression.setup(hub,f.session,p.session,m.session,o.session);if(app)NativeDeItemApplication.install(hub,templates,definitions);room=(long)get(p.session,"currentRoomId");roomState=FlowRegression.room(hub,room);oldRules=((BattleRules.MatchState)get(roomState,"match")).rules();for(String label:List.of("WORLD-COMPANION-PET","WORLD-COMPANION-SUMMON","WORLD-COMPANION-TAMED"))one(p.session,f.session,hub,label);}check(!Files.exists(dir.resolve("must-not-write.properties")),"memory-only accepted Frame fixture");
